import{_ as t,o as s,c as r,ak as o}from"./chunks/framework.sV-XtlWr.js";const a="/screenshots/permission-grid.png",m=JSON.parse('{"title":"Project access","description":"Scope Reporter and User accounts to the projects assigned to them, globally or per project, and edit every assignment on the permission grid.","frontmatter":{"title":"Project access","description":"Scope Reporter and User accounts to the projects assigned to them, globally or per project, and edit every assignment on the permission grid.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/project-access.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/project-access.html"}],["meta",{"property":"og:title","content":"Project access | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Scope Reporter and User accounts to the projects assigned to them, globally or per project, and edit every assignment on the permission grid."}]]},"headers":[],"relativePath":"operate/project-access.md","filePath":"operate/project-access.md","lastUpdated":1790454954000}'),n={name:"operate/project-access.md"};function i(c,e,l,d,h,g){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="project-access" tabindex="-1">Project access <a class="header-anchor" href="#project-access" aria-label="Permalink to &quot;Project access&quot;">​</a></h1><p>Administrators see every project. <strong>Reporter</strong> and <strong>User</strong> accounts see only the projects they are <strong>assigned</strong> to, so you can give each team its own slice of the dashboard. Project access applies only with <a href="./authentication.html">authentication</a> on; the <a href="./authentication.html#roles">roles</a> say what each account can do inside the projects it opens.</p><p>An assignment is one of two kinds:</p><ul><li><strong>Global</strong>: access to <em>all</em> projects, including ones created later. Good for a shared CI reporter or a team lead.</li><li><strong>Per-project</strong>: access to a specific set of projects only.</li></ul><p>What scoping affects for a non-admin user:</p><ul><li>The project list, sidebar menu, home dashboard, recent runs, and search only include assigned projects.</li><li>Runs, test cases, and clusters that belong to an unassigned project return <strong>403</strong>.</li><li>A reporter can submit results to an assigned project. Creating a <strong>new</strong> project on first submission requires <strong>global</strong> access: a per-project reporter can&#39;t invent projects.</li></ul><blockquote><p><strong>Default is no access.</strong> A freshly created Reporter or User has no assignments and sees an empty dashboard until you grant some, and so does an account whose last project you revoke. (Once, on a database with no assignments yet, existing Reporter and User accounts are given global access, so upgrading from a version without project access changes nothing for them.)</p></blockquote><h2 id="managing-assignments" tabindex="-1">Managing assignments <a class="header-anchor" href="#managing-assignments" aria-label="Permalink to &quot;Managing assignments&quot;">​</a></h2><p>Assignments are administrator-only and can be edited from three places:</p><ul><li><strong>All at once</strong>: <strong>Settings → Permissions</strong>, the <a href="#permission-grid">permission grid</a>: every user against every project.</li><li><strong>Per user</strong>: <strong>Settings → Users → Project access</strong> (the action next to a user). Choose global access or tick specific projects.</li><li><strong>Per project</strong>: the <strong>Members</strong> section of a project&#39;s <strong>Settings</strong> tab. Add or remove users for that one project.</li></ul><p>All three edit the same underlying assignments, so use whichever is more convenient.</p><h2 id="permission-grid" tabindex="-1">Permission grid <a class="header-anchor" href="#permission-grid" aria-label="Permalink to &quot;Permission grid&quot;">​</a></h2><p><strong>Settings → Permissions</strong> lays every user against every project on one grid, so you can read and change access for the whole instance without opening accounts one at a time. Rows are users, grouped by role; columns are projects, after an <strong>All projects</strong> column. A tick grants that role in that project: a reporter can upload results and triage there, a user can read.</p><div class="doc-screenshot"><img src="'+a+'" alt="Settings → Permissions: users grouped by role down the side, projects across the top, and the focused cell&#39;s row and column highlighted"></div><ul><li><strong>Every click saves at once</strong>; there is no Save button. A change the server refuses is rolled back and reported.</li><li><strong>All projects</strong> also covers projects created later. While it is ticked, the user&#39;s project cells show a faint tick and are locked; unticking it returns the user to exactly the projects ticked one by one.</li><li><strong>Administrators</strong> open every project, so their row is ticked and locked.</li><li><strong>Hovering a cell highlights its row and column</strong>, so a cell far from the headers still reads against its user and its project. Keyboard focus does the same: Tab enters the grid as one stop, the arrow keys move between cells, Space toggles.</li><li><strong>Filter users</strong> and <strong>Filter projects</strong> narrow the grid on a large instance.</li></ul><p>Scripts can read and change the same assignments through the API; see the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a>.</p><blockquote><p><strong>Try it in the demo:</strong> the <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> ships with several pre-seeded identities: an admin, a global CI reporter, and users scoped to one or two projects (plus one with none). Use the <strong>Acting as</strong> picker in the demo banner to switch between them and watch the project list, sidebar, and search change to match each user&#39;s access. Acting as the admin, change the assignments live and switch back to see the effect. See <a href="/features/ui-overview.html#live-demo">UI overview → Live demo</a>.</p></blockquote><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./authentication.html">Authentication</a>: turning sign-in on, roles and user management</li><li><a href="./api-keys.html">API keys</a>: a key acts with its owner&#39;s role and project access</li><li><a href="./production-checklist.html">Production checklist</a>: what to set before anyone else can reach the instance</li></ul>',19)])])}const u=t(n,[["render",i]]);export{m as __pageData,u as default};
